/* Independent Z80 vectors replayed through the CPS-1 Z80 generator path.
 *
 * The vectors are SingleStepTests/z80 data (MIT, generated by JSMoo, not recorded from hardware). The code under test
 * is the project's own: the CPS-1 translated Z80 bodies (retrorecomp/cps1_codegen.generate_z80) dispatched by the patched
 * Geolith Z80 core exactly as in a CPS-1 game (rr_cps1_z80_try, with its byte guard), and the same core with every
 * instruction interpreted. The bus is flat (64 KiB, no board); the vector's own ports answer in and out.
 *
 * A vector whose code lies in the sound ROM windows or in sound RAM runs natively; the harness only substitutes the
 * location of the instruction in the generated image (one image slot per distinct opcode form), because the vectors'
 * addresses collide. A vector whose code lies elsewhere has no native step on the board: it runs interpreted and the
 * interpreter counter must say so. Each vector runs on both paths and is compared with the vector's final registers,
 * written bytes, ports and clock count (SR bits 3 and 5 included, WZ included, P and Q excluded: the core has neither). */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include "z80.h"
#include "cps1_z80_native.h"

#define NO_SLOT 0xffffffffu
#define FIELDS 22   /* pc sp a f b c d e h l i r ix iy wz af_ bc_ de_ hl_ im iff1 iff2 */
static const char *const field_names[FIELDS] = {"pc", "sp", "a", "f", "b", "c", "d", "e", "h", "l", "i", "r", "ix", "iy", "wz",
                                                "af_", "bc_", "de_", "hl_", "im", "iff1", "iff2"};

int rr_cps1_force_reference, rr_cps1_force_z80_reference;
uint64_t rr_cps1_native_z80, rr_cps1_interpreted_z80;

static uint8_t memory[65536], expected[65536];
static uint32_t current_slot = NO_SLOT, current_pc;
static struct { uint32_t address, value, direction; } ports[8];
static unsigned port_count, port_used;
static int port_error;

int rr_cps1_z80_code_location(uint16_t pc, uint32_t *offset) {
    if (current_slot == NO_SLOT || pc != current_pc) return 0;
    *offset = current_slot;
    return 1;
}
int rr_cps1_z80_code_byte(uint16_t pc, uint8_t *byte) { *byte = memory[pc]; return 1; }
void rr_cps1_z80_note_fallback(uint16_t pc) { (void)pc; ++rr_cps1_interpreted_z80; }

static uint8_t bus_read(void *u, uint16_t a) { (void)u; return memory[a]; }
static void bus_write(void *u, uint16_t a, uint8_t v) { (void)u; memory[a] = v; }
static uint8_t port_in(z80 *z, uint16_t a) {
    (void)z;
    if (port_used >= port_count || ports[port_used].direction != 'r' || ports[port_used].address != a) { port_error = 1; return 0; }
    return (uint8_t)ports[port_used++].value;
}
static void port_out(z80 *z, uint16_t a, uint8_t v) {
    (void)z;
    if (port_used >= port_count || ports[port_used].direction != 'w' || ports[port_used].address != a ||
        ports[port_used].value != v) { port_error = 1; return; }
    ++port_used;
}

static uint32_t word(FILE *file) {
    uint32_t v;
    if (fread(&v, 4, 1, file) != 1) { fprintf(stderr, "truncated vectors\n"); exit(2); }
    return v;
}

static void load(z80 *z, const uint32_t *r) {
    z80_init(z);
    z->read_byte = bus_read; z->write_byte = bus_write; z->port_in = port_in; z->port_out = port_out;
    z->pc = (uint16_t)r[0]; z->sp = (uint16_t)r[1]; z->a = (uint8_t)r[2]; z->f = (uint8_t)r[3];
    z->b = (uint8_t)r[4]; z->c = (uint8_t)r[5]; z->d = (uint8_t)r[6]; z->e = (uint8_t)r[7];
    z->h = (uint8_t)r[8]; z->l = (uint8_t)r[9]; z->i = (uint8_t)r[10]; z->r = (uint8_t)r[11];
    z->ix = (uint16_t)r[12]; z->iy = (uint16_t)r[13]; z->mem_ptr = (uint16_t)r[14];
    z->a_f_ = (uint16_t)r[15]; z->b_c_ = (uint16_t)r[16]; z->d_e_ = (uint16_t)r[17]; z->h_l_ = (uint16_t)r[18];
    z->interrupt_mode = (uint8_t)r[19]; z->iff1 = r[20] != 0; z->iff2 = r[21] != 0;
    z->iff_delay = 0;   /* an inherited EI delay is not part of the comparison; interrupts are tested elsewhere */
}
static void save(const z80 *z, uint32_t *r) {
    r[0] = z->pc; r[1] = z->sp; r[2] = z->a; r[3] = z->f; r[4] = z->b; r[5] = z->c; r[6] = z->d; r[7] = z->e;
    r[8] = z->h; r[9] = z->l; r[10] = z->i; r[11] = z->r; r[12] = z->ix; r[13] = z->iy; r[14] = z->mem_ptr;
    r[15] = z->a_f_; r[16] = z->b_c_; r[17] = z->d_e_; r[18] = z->h_l_; r[19] = z->interrupt_mode; r[20] = z->iff1; r[21] = z->iff2;
}

typedef struct { uint32_t cases, ran_native, ran_interpreted, state, clock, ports_ok; } Counts;
typedef struct {
    char name[16];
    Counts native, reference;
    unsigned equal, equal_clock;
    unsigned field[FIELDS + 2];   /* native path: vectors that differ on each field, then bytes written, then ports */
} Family;
static Family families[2048];
static unsigned family_count;
static unsigned field_fail[2][FIELDS], memory_fail[2], port_fail[2];
static char examples[64][200];
static unsigned example_count;

static Family *family_of(const char *name) {
    for (unsigned i = 0; i < family_count; ++i) if (!strcmp(families[i].name, name)) return &families[i];
    if (family_count >= 2048) exit(2);
    snprintf(families[family_count].name, sizeof families[0].name, "%s", name);
    return &families[family_count++];
}

int main(int argc, char **argv) {
    if (argc != 2) return 2;
    FILE *file = fopen(argv[1], "rb");
    if (!file) return 2;
    const uint32_t count = word(file);
    static uint8_t bytes[65536];
    uint64_t native_counted_ok = 0, interpreted_counted_ok = 0, in_map = 0, outside = 0, rom_map = 0, ram_map = 0;
    uint32_t after[2][FIELDS];
    unsigned cycles_after[2];
    for (uint32_t n = 0; n < count; ++n) {
        const uint32_t slot = word(file), expected_cycles = word(file);
        char name[16] = {0};
        for (unsigned k = 0; k < 3; ++k) { const uint32_t w = word(file); memcpy(name + 4 * k, &w, 4); }
        uint32_t initial[FIELDS], final[FIELDS];
        for (unsigned i = 0; i < FIELDS; ++i) initial[i] = word(file);
        for (unsigned i = 0; i < FIELDS; ++i) final[i] = word(file);
        memset(bytes, 0xA5, sizeof bytes);
        for (unsigned k = word(file); k; --k) { const uint32_t a = word(file); bytes[a & 0xffff] = (uint8_t)word(file); }
        memcpy(expected, bytes, sizeof expected);
        for (unsigned k = word(file); k; --k) { const uint32_t a = word(file); expected[a & 0xffff] = (uint8_t)word(file); }
        port_count = word(file);
        if (port_count > 8) return 2;
        for (unsigned k = 0; k < port_count; ++k) { ports[k].address = word(file); ports[k].value = word(file); ports[k].direction = word(file); }
        Family *f = family_of(name);
        ++f->native.cases; ++f->reference.cases;
        for (int reference = 0; reference < 2; ++reference) {
            memcpy(memory, bytes, sizeof memory);
            port_used = 0; port_error = 0;
            rr_cps1_force_reference = rr_cps1_force_z80_reference = reference;
            current_pc = initial[0]; current_slot = reference ? NO_SLOT : slot;
            const uint64_t native_before = rr_cps1_native_z80, interpreted_before = rr_cps1_interpreted_z80;
            z80 z;
            load(&z, initial);
            const unsigned cyc = z80_step(&z);
            save(&z, after[reference]);
            cycles_after[reference] = cyc;
            Counts *c = reference ? &f->reference : &f->native;
            const int native_ran = rr_cps1_native_z80 - native_before == 1;
            const int interpreted_ran = rr_cps1_interpreted_z80 - interpreted_before == 1;
            if (!reference) {
                /* The native path must be the one the board has: native where the code is mapped, counted otherwise. */
                if (slot != NO_SLOT || (initial[0] >= 0xd000u && initial[0] < 0xd800u)) { if (native_ran && !interpreted_ran) ++native_counted_ok; }
                else if (!native_ran && interpreted_ran) ++interpreted_counted_ok;
                if (native_ran) ++c->ran_native; else if (interpreted_ran) ++c->ran_interpreted;
            }
            int bad_field = -1;
            for (unsigned i = 0; i < FIELDS; ++i) if (after[reference][i] != final[i]) { if (bad_field < 0) bad_field = (int)i; ++field_fail[reference][i]; if (!reference) ++f->field[i]; }
            const int memory_ok = !memcmp(memory, expected, sizeof memory);
            const int ports_ok = !port_error && port_used == port_count;
            if (!memory_ok) { ++memory_fail[reference]; if (!reference) ++f->field[FIELDS]; }
            if (!ports_ok) { ++port_fail[reference]; if (!reference) ++f->field[FIELDS + 1]; }
            c->state += bad_field < 0 && memory_ok && ports_ok;
            c->clock += cyc == expected_cycles;
            c->ports_ok += ports_ok;
            if ((bad_field >= 0 || !memory_ok || !ports_ok) && example_count < 64 && f->native.cases - f->native.state + f->reference.cases - f->reference.state <= 2)
                snprintf(examples[example_count++], sizeof examples[0], "%s #%u %s %s", name, n, reference ? "reference" : "native",
                         bad_field >= 0 ? field_names[bad_field] : !memory_ok ? "memory" : "ports");
        }
        const int same = !memcmp(after[0], after[1], sizeof after[0]);
        f->equal += same; f->equal_clock += cycles_after[0] == cycles_after[1];
        if (slot != NO_SLOT) ++rom_map; else if (initial[0] >= 0xd000u && initial[0] < 0xd800u) ++ram_map; else ++outside;
        (void)in_map;
    }
    fclose(file);
    printf("{\"cases\":%u,\"rom_mapped\":%llu,\"ram_mapped\":%llu,\"outside_code_map\":%llu,\"native_as_expected\":%llu,"
           "\"interpreted_and_counted_as_expected\":%llu,\"families\":[", count, (unsigned long long)rom_map, (unsigned long long)ram_map,
           (unsigned long long)outside, (unsigned long long)native_counted_ok, (unsigned long long)interpreted_counted_ok);
    Counts total_n = {0}, total_r = {0};
    unsigned equal = 0, equal_clock = 0;
    for (unsigned i = 0; i < family_count; ++i) {
        const Family *f = &families[i];
        printf("%s{\"family\":\"%s\",\"cases\":%u,\"native_state\":%u,\"reference_state\":%u,\"native_clock\":%u,\"reference_clock\":%u,"
               "\"paths_equal\":%u,\"paths_clock_equal\":%u,\"native_fields\":{", i ? "," : "", f->name, f->native.cases, f->native.state, f->reference.state,
               f->native.clock, f->reference.clock, f->equal, f->equal_clock);
        int first_field = 1;
        for (unsigned k = 0; k < FIELDS + 2; ++k) if (f->field[k]) {
            printf("%s\"%s\":%u", first_field ? "" : ",", k < FIELDS ? field_names[k] : k == FIELDS ? "memory" : "ports", f->field[k]);
            first_field = 0;
        }
        printf("}}");
        total_n.cases += f->native.cases; total_n.state += f->native.state; total_r.state += f->reference.state;
        total_n.clock += f->native.clock; total_r.clock += f->reference.clock; equal += f->equal; equal_clock += f->equal_clock;
        total_n.ran_native += f->native.ran_native; total_n.ran_interpreted += f->native.ran_interpreted;
    }
    printf("],\"totals\":{\"native_state\":%u,\"reference_state\":%u,\"native_clock\":%u,\"reference_clock\":%u,\"paths_equal\":%u,"
           "\"paths_clock_equal\":%u,\"ran_native\":%u,\"ran_interpreted\":%u},\"field_failures\":{", total_n.state, total_r.state, total_n.clock,
           total_r.clock, equal, equal_clock, total_n.ran_native, total_n.ran_interpreted);
    for (int path = 0; path < 2; ++path) {
        printf("%s\"%s\":{", path ? "," : "", path ? "reference" : "native");
        int first = 1;
        for (unsigned i = 0; i < FIELDS; ++i) if (field_fail[path][i]) { printf("%s\"%s\":%u", first ? "" : ",", field_names[i], field_fail[path][i]); first = 0; }
        printf("%s\"memory\":%u,\"ports\":%u}", first ? "" : ",", memory_fail[path], port_fail[path]);
    }
    printf("},\"examples\":[");
    for (unsigned i = 0; i < example_count; ++i) printf("%s\"%s\"", i ? "," : "", examples[i]);
    printf("]}\n");
    return 0;
}
